#!/bin/bash
# The app icon is the one asset the user sees before they open anything, and nothing checked
# it: the three PNGs and the catalog were regenerated by hand, and the only thing that had
# ever looked at them was a person. This asserts what the generator promises and what Xcode
# needs - 1024 square, opaque, non-empty, and a catalog that names exactly the files that are
# present - so a bad regeneration cannot ship quietly.
#
# It does not look at the picture. Whether the artwork is the right artwork is a judgement and
# is recorded in development/ICON.md; this is the part a script can hold.
set -euo pipefail
cd "$(dirname "$0")/../.." || exit 2

set_name=wolkara/Shell/Assets.xcassets/Wolkara.appiconset
source_image=wolkara/Shell/artwork/wolkara-icon-source.png
failures=0
checks=0
# Written as two helpers used inside `if`/`else` rather than `[ ... ]; check $?`, because a
# bare failing test under `set -e` ends the script - which is exactly how the first version of
# this file stopped after its second-to-last check and printed no verdict at all.
ok() { checks=$((checks + 1)); echo "ok   $1"; }
no() { checks=$((checks + 1)); echo "FAIL $1"; failures=$((failures + 1)); }

[ -d "$set_name" ] || { echo "FAIL $set_name is missing"; exit 1; }
[ -f "$source_image" ] || { echo "FAIL $source_image is missing, so the icon cannot be regenerated"; exit 1; }

for appearance in default dark tinted; do
    asset="$set_name/Wolkara-$appearance.png"
    if [ ! -s "$asset" ]; then
        no "Wolkara-$appearance.png exists and is not empty"
        continue
    fi
    width=$(sips -g pixelWidth "$asset" | sed -n 's/.*pixelWidth: //p' | tr -d ' ')
    height=$(sips -g pixelHeight "$asset" | sed -n 's/.*pixelHeight: //p' | tr -d ' ')
    alpha=$(sips -g hasAlpha "$asset" | sed -n 's/.*hasAlpha: //p' | tr -d ' ')
    if [ "$width" = 1024 ] && [ "$height" = 1024 ]; then
        ok "Wolkara-$appearance.png is 1024x1024"
    else
        no "Wolkara-$appearance.png is 1024x1024 (got ${width}x${height})"
    fi
    # An app icon must be opaque all the way into its corners: iOS does not draw a background
    # behind it, so alpha there shows as black. The generator strips it through sips; this is
    # what notices if that step is ever lost.
    if [ "$alpha" = no ]; then
        ok "Wolkara-$appearance.png has no alpha channel"
    else
        no "Wolkara-$appearance.png has no alpha channel (got hasAlpha=${alpha})"
    fi
done

# The catalog has to name exactly what is on disk: a filename that is not there is a build
# error, and a PNG that is not named is an asset nothing will ever load.
present=$(ls "$set_name" | grep -c '\.png$' || true)
named=$(sed -n 's/.*"filename" *: *"\([^"]*\)".*/\1/p' "$set_name/Contents.json" | sort -u)
expected=$(printf '%s\n' Wolkara-default.png Wolkara-dark.png Wolkara-tinted.png | sort -u)
if [ "$named" = "$expected" ]; then
    ok "the catalog names the three appearances and nothing else"
else
    no "the catalog names exactly the three appearances (got: $(echo "$named" | tr '\n' ' '))"
fi
for name in $named; do
    if [ -s "$set_name/$name" ]; then
        ok "the catalog names $name, which is present"
    else
        no "the catalog names $name, which is present"
    fi
done
if [ "$present" -eq 3 ]; then
    ok "there are exactly three PNGs in the set"
else
    no "there are exactly three PNGs in the set (got $present)"
fi

# The three entries must be the single 1024 universal asset iOS derives the rest from, with
# dark and tinted declared as luminosity appearances - that is what makes those two render on
# the home screen at all, and it is what the generator writes.
if [ "$(grep -c '"size" *: *"1024x1024"' "$set_name/Contents.json")" -eq 3 ]; then
    ok "all three entries are the 1024x1024 universal asset"
else
    no "all three entries are the 1024x1024 universal asset"
fi
if [ "$(grep -c '"appearance" *: *"luminosity"' "$set_name/Contents.json")" -eq 2 ]; then
    ok "dark and tinted are declared as appearances rather than separate idiom entries"
else
    no "dark and tinted are declared as luminosity appearances (got $(grep -c '"appearance" *: *"luminosity"' "$set_name/Contents.json"))"
fi
if [ "$(grep -c '"idiom" *: *"universal"' "$set_name/Contents.json")" -eq 3 ]; then
    ok "all three entries are universal"
else
    no "all three entries are universal"
fi

echo
if [ "$failures" -eq 0 ]; then
    echo "ICON PASS: $checks checks"
    exit 0
fi
echo "ICON FAIL: $failures of $checks checks failed"
exit 1
